input_path = Path('/root/environment/data/ckd_lab_data.csv')
raw = pd.read_csv(input_path, dtype=str)
cols=list(raw.columns)
numeric_cols=[c for c in cols if c!='patient_id']

def parse_value(v):
    if v is None:
        return np.nan
    s=str(v).strip()
    if s=='' or s.lower() in {'nan','none','null'}:
        return np.nan
    if ',' in s and '.' in s:
        if s.rfind(',')>s.rfind('.'):
            s=s.replace('.','').replace(',','.')
        else:
            s=s.replace(',','')
    elif ',' in s:
        parts=s.split(',')
        if len(parts)>1 and all(p.isdigit() and len(p)==3 for p in parts[1:]):
            s=s.replace(',','')
        else:
            s=s.replace(',','.')
    try:
        return float(s)
    except:
        return np.nan

parsed=raw.copy()
for c in numeric_cols:
    parsed[c]=parsed[c].map(parse_value)
parsed['patient_id']=raw['patient_id'].astype(str).str.strip()
parsed.loc[parsed['patient_id'].isin(['','nan','None','null']),'patient_id']=np.nan
parsed=parsed.dropna(subset=['patient_id']+numeric_cols).reset_index(drop=True)

# reuse the same ranges/conversions from previous run by reading them from the output script? We'll redefine quickly
