for c in numeric_cols:
    if c not in R:
        continue
    lo,hi=R[c]
    oor = (~harm[c].between(lo,hi)).sum()
    report.append((oor,c,harm[c].min(),harm[c].max(),lo,hi))

report.sort(reverse=True)
print('top out-of-range columns:')
for oor,c,mn,mx,lo,hi in report[:15]:
    print(f"{c:35s} oor={oor:4d} min={mn:12.4g} max={mx:12.4g} range=[{lo},{hi}]")

# show some example extreme values for worst column
worst=report[0][1]
lo,hi=R[worst]
ex=harm.loc[(harm[worst]<lo)|(harm[worst]>hi), ['patient_id',worst]].head(10)
print('\nworst examples:', worst)
print(ex.to_string(index=False))
